        b = int(data[idx + 1])
        idx += 2
        adj[a].append(b)
        adj[b].append(a)

    good = [False] * (n + 1)
    for i in range(1, n + 1):
        good[i] = len(adj[i]) >= 4

    visited = [False] * (n + 1)
    best = 0

    for s in range(1, n + 1):
        if not good[s] or visited[s]:
            continue

